#include <command.h>
#include "../include/utils/io.h"

#define AUXDISP_BADDR       0x06740000
#define HDMI_BADDR          0x06600000

static void set_auxdisp_data(void){  // 1920x1080 HDMI output
    u32 rdata = 0;
    
    wr(AUXDISP_BADDR + 0x100, 0x2f);

    rdata = rd(AUXDISP_BADDR + 0x4);
    //wr(AUXDISP_BADDR + 0x4, 0x20d035a); // Vertical total , Horizontal total
    wr(AUXDISP_BADDR + 0x4, 0x4650898); // Vertical total , Horizontal total

    rdata = rd(AUXDISP_BADDR + 0x8); // TO DO:0x1e002d0
    wr(AUXDISP_BADDR + 0x8, 0x4380780);  // 1920x1080  vertial active, horizontal active
    //wr(AUXDISP_BADDR + 0x8, 0x1e002d0);

    rdata = rd(AUXDISP_BADDR + 0xc);   // TO DO:0x3c003e
    wr(AUXDISP_BADDR + 0xc, 0x94002c); // horizontal back porch  + horizontall sync width
    rdata = rd(AUXDISP_BADDR + 0x10);
    wr(AUXDISP_BADDR + 0x10, 0x58);    // horizontal front porch

    rdata = rd(AUXDISP_BADDR + 0x14);  // TO DO:0x1e0006
    wr(AUXDISP_BADDR + 0x14, 0x240005);// vertical back porch  + verical sync width
    rdata = rd(AUXDISP_BADDR + 0x18);  // TO DO:0x9  vertical front porch
    wr(AUXDISP_BADDR + 0x18, 0x4);     // vertical front porch
    
    rdata = rd(AUXDISP_BADDR + 0x44); // TO DO:0x1e002d0
    wr(AUXDISP_BADDR + 0x44, 0x4380780);  // 1920x1080  video height, video width
    //wr(AUXDISP_BADDR + 0x44, 0x1e002d0); // 720x480

    rdata = rd(AUXDISP_BADDR + 0x20); // TO DO:0x10
    wr(AUXDISP_BADDR + 0x20, 0x24);    // number of delayed line from vsync

    rdata = rd(AUXDISP_BADDR + 0x1c); // TO DO:0x0
    wr(AUXDISP_BADDR + 0x1c, 0x10);   // display output mode

    rdata = rd(AUXDISP_BADDR + 0x24); // TO DO:0x7
    wr(AUXDISP_BADDR + 0x24, 0x4);    // polarity control

    rdata = rd(AUXDISP_BADDR + 0x2c); // TO DO:0x800000900
    wr(AUXDISP_BADDR + 0x2c, 0x800000030); // pattern contorl

    rdata = rd(AUXDISP_BADDR + 0x2c); // TO DO:0x80000030
    wr(AUXDISP_BADDR + 0x2c, 0x800000031);

    rdata = rd(AUXDISP_BADDR + 0x0); // TO DO:0x0
    wr(AUXDISP_BADDR + 0x0, 0x1);    // dispaly output enable

    rdata = rd(AUXDISP_BADDR + 0x10c); // TO DO:0x1
    wr(AUXDISP_BADDR + 0x104, 0x1); // interrupt status.
    rdata = rd(AUXDISP_BADDR + 0x10c); // TO DO:0x2
    wr(AUXDISP_BADDR + 0x104, 0x2);
    rdata = rd(AUXDISP_BADDR + 0x10c); // TO DO:0x1
    wr(AUXDISP_BADDR + 0x104, 0x1);
    rdata = rd(AUXDISP_BADDR + 0x10c); // TO DO:0x2
    wr(AUXDISP_BADDR + 0x104, 0x2);
    rdata = rd(AUXDISP_BADDR + 0x10c); // TO DO:0x1
    wr(AUXDISP_BADDR + 0x104, 0x1);

}
